  "results.title": "Results",
  "results.roundDate": "Round {date}",
  "results.responseRate": "{rate}% response rate ({responses} of {eligible})",
  "results.responseCount": "{count} responses",
  "results.openNotice":
    "This Round is currently open. Results will be calculated and shared after it closes.",
