  "results.biggerChangeThanUsual": "Bigger change than usual for this team",
import { catalog } from "./catalog.ts";

type Catalog = typeof catalog;
export type MessageKey = keyof Catalog;
type Value = string | number;

type Placeholders<T extends string> = T extends `${string}{${infer Name}}${infer Rest}`
  ? Name | Placeholders<Rest>
  : never;
type Params<K extends MessageKey> = Readonly<Record<Placeholders<Catalog[K]>, Value>>;
type KeysWithoutParams = {
  [K in MessageKey]: [Placeholders<Catalog[K]>] extends [never] ? K : never;
}[MessageKey];
type KeysWithParams = Exclude<MessageKey, KeysWithoutParams>;

type PluralBase<K extends string> = K extends `${infer Base}.other` ? Base : never;
export type PluralKey = PluralBase<MessageKey>;
type PluralParams<B extends PluralKey> = Readonly<
  Record<Exclude<Placeholders<Catalog[`${B}.other`]>, "count">, Value>
>;

const LOCALE = "en";
let cachedPluralRules: Intl.PluralRules | undefined;
function getPluralRules(): Intl.PluralRules {
  if (!cachedPluralRules) {
    cachedPluralRules = new Intl.PluralRules(LOCALE);
  }
  return cachedPluralRules;
}

const isMessageKey = (key: string): key is MessageKey => Object.hasOwn(catalog, key);

function fill(template: string, params: Readonly<Record<string, Value>>): string {
  return template.replace(/\{(\w+)\}/g, (_, name: string) => String(params[name] ?? ""));
}

/** Looks up a message; placeholders are checked against the template at compile time. */
export function message<K extends KeysWithoutParams>(key: K): string;
export function message<K extends KeysWithParams>(key: K, params: Params<K>): string;
export function message(key: MessageKey, params: Readonly<Record<string, Value>> = {}): string {
  return fill(catalog[key], params);
}

/** Picks the plural form for `count` with `Intl.PluralRules`; `{count}` is filled in. */

import { Dimension } from "@surveybeat/domain";
import * as Arbitrary from "effect/Arbitrary";
import * as Schema from "effect/Schema";
import type { HttpApi, HttpApiGroup } from "effect/http-api";
import type { SurveyBeatApi } from "./index.ts";

/** `group.endpoint` for every endpoint of an HttpApi declaration. */
export type EndpointKey<Api> =
  Api extends HttpApi.HttpApi<infer _Id, infer Groups>
    ? Groups extends HttpApiGroup.Constraint
      ? `${Groups["identifier"]}.${HttpApiGroup.Endpoints<Groups>["identifier"]}`
      : never
    : never;

const between = (minimum: number, maximum: number) =>
  Schema.Int.pipe(Schema.check(Schema.isGreaterThanOrEqualTo(minimum), Schema.isLessThanOrEqualTo(maximum)));

/** How many Questions a generated Round can have; every per-Question list below has this many slots. */
export const SCENARIO_QUESTION_SLOTS = 5;

const slots = <S extends Schema.Constraint>(item: S) =>
  Schema.Array(item).pipe(
    Schema.check(Schema.isMinLength(SCENARIO_QUESTION_SLOTS), Schema.isMaxLength(SCENARIO_QUESTION_SLOTS)),
  );

/** One Question of a generated Round. `kind` picks the Question type; `dimension` is null for none. */
const ScenarioQuestion = Schema.Struct({
  kind: Schema.Literals(["rating", "choice", "text"]),
  dimension: Schema.NullOr(Dimension),
});

/** What one generated Submission answered for one Question slot (`value` is read per the Question kind). */
const ScenarioAnswer = Schema.Struct({
  answered: Schema.Boolean,
  value: between(0, 4),
  comment: Schema.NullOr(Schema.Literals(["", "   ", "fine", "too much work", "Ask Anna"])),
});

/** An earlier Round's score for one Dimension, in `Dimension` order. */
const ScenarioDimension = Schema.Struct({
  score: Schema.NullOr(between(1, 5)),
  usableQuestionCount: between(0, 3),
  contributors: between(0, 14),
});

/** An earlier closed Round of the same Pulse, as the Result computation sees it. */
const ScenarioHistoryRound = Schema.Struct({
  effectiveMinimumGroupSize: between(1, 8),
  submissionsCount: between(0, 14),
  questions: slots(Schema.Struct({ score: Schema.NullOr(between(1, 5)), contributors: between(0, 14) })),
  dimensions: Schema.Tuple([ScenarioDimension, ScenarioDimension, ScenarioDimension, ScenarioDimension]),
});

/**
 * The raw material for one Round's Result: the Round's status, the minimum group size stored when
 * its Result was computed (`storedN`), the Organization's minimum group size now (`organizationN`,
 * which may have been raised since), its Team size, Questions, Submissions, and earlier Rounds. The
 * effective N is `max(storedN, organizationN)` (ADR 0004, Rule R9).
 */
export const RoundResultScenario = Schema.Struct({

    // Property test over the registry's own generator: whatever Round the generator produces, the
    // endpoint's Result shows no aggregate computed from fewer than the effective N contributors.
    it.effect(`${key}: no aggregate below the effective N for any generated Round (ADR 0004)`, () =>
      Effect.gen(function* () {
        assert.isDefined(respond, `no Result check registered for ${key}`);
        const check = yield* Arbitrary.checkEffect(
          entry.inputs,
          (input) =>
            Effect.suspend(() => {
              const scenario = Schema.decodeUnknownSync(RoundResultScenario)(input);
              const failures = violations(scenario, respond(scenario));
              return failures.length > 0 ? Effect.fail(failures.join("; ")) : Effect.succeed(true);
            }),
          { runs: 500, seed: 20261109 },
        );
        assert.strictEqual(Arbitrary.formatCheckFailure(check), undefined);
        assert.strictEqual(check._tag, "Passed");
      }),
    );
  }
});

// --- The Result-shaped response of each Result-bearing endpoint, built the way the handler builds it ---

interface Built {
  readonly effectiveN: number;
